    public static void TestAesFips197OneBlock() {
        // FIPS 197 C.1 and C.3: AES-128 and AES-256, a zero IV makes CBC one ECB block.
        emon.Port.Cells o = emon.Port.NewCells();
        emon.Port.Cells p = emon.Port.NewCells();
        emon.Port.Cells q = emon.Port.NewCells();
        emon.Port.Cells r = emon.Port.NewCells();
        emon.Testport.AssertEq(emon.Port.CryptoAesEncrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("00000000000000000000000000000000 00112233445566778899aabbccddeeff"), 0, 32, o), 16, "one block out");
        emon.Testport.AssertCellsHex(o, "69c4e0d86a7b0430d8cdb78070b4c55a", "AES-128 encrypt");
        emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("00000000000000000000000000000000 69c4e0d86a7b0430d8cdb78070b4c55a"), 0, 32, 0, p);
        emon.Testport.AssertCellsHex(p, "00112233445566778899aabbccddeeff", "AES-128 decrypt");
        emon.Port.CryptoAesEncrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, emon.Testport.HexBlob("00000000000000000000000000000000 00112233445566778899aabbccddeeff"), 0, 32, q);
        emon.Testport.AssertCellsHex(q, "8ea2b7ca516745bfeafc49904b496089", "AES-256 encrypt");
        emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, emon.Testport.HexBlob("00000000000000000000000000000000 8ea2b7ca516745bfeafc49904b496089"), 0, 32, 0, r);
        emon.Testport.AssertCellsHex(r, "00112233445566778899aabbccddeeff", "AES-256 decrypt");
    }
