    [Xunit.Fact]
    public static void TestAesPaddingIsStrippedOnlyWhenAsked() {
        // Ciphertext made by the JDK's AES/CBC/PKCS5Padding; key 00..0f, IV 0f..00.
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells c = emon.Port.NewCells();
        emon.Port.Cells d = emon.Port.NewCells();
        emon.Port.Cells e = emon.Port.NewCells();
        emon.Testport.AssertEq(emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489"), 0, 32, 1, a), 5, "five bytes once the padding is gone");
        emon.Testport.AssertCellsHex(a, "68656c6c6f", "hello");
        emon.Testport.AssertEq(emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489"), 0, 32, 0, b), 16, "sixteen with pad 0");
        emon.Testport.AssertCellsHex(b, "68656c6c6f0b0b0b0b0b0b0b0b0b0b0b", "the padding is kept when not asked");
        emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("0f0e0d0c0b0a09080706050403020100 ff14dbe405cc0ee24d0de41289f0fc981c8a2100b00814723d26cb8858d62767"), 0, 48, 1, c);
        emon.Testport.AssertCellsHex(c, "303132333435363738396162636465666768696a", "twenty bytes across two blocks");
        emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, emon.Testport.HexBlob("0f0e0d0c0b0a09080706050403020100 ff14dbe405cc0ee24d0de41289f0fc988680054fc9016bbf4f4067cd27826cdb"), 0, 48, 1, d);
        emon.Testport.AssertCellsHex(d, "30313233343536373839616263646566", "sixteen bytes: a whole block of padding is removed");
        emon.Port.CryptoAesDecrypt(emon.Testport.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, emon.Testport.HexBlob("0f0e0d0c0b0a09080706050403020100 2e5a65859a9f16ccfc0dddb5306145a9"), 0, 32, 1, e);
        emon.Testport.AssertCellsHex(e, "68656c6c6f", "AES-256 padded");
    }
